const $=id=>document.getElementById(id),PX=3.6,clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),round=v=>Math.round(v*1000)/1000;
let source,state,selected=null,zoom=1,drag=null,past=[],future=[],revision=0,pending=false,saving=false,enabled=false,saveTimer,editVersion=0,conflictEnvelope=null,initialised=false;
const element=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
function status(text,kind=''){ $('status').textContent=text;$('status').dataset.kind=kind; }
const key=()=>`figure-layout:${source.projectId}:sync`;
function initial(){return {panels:source.panels.map(p=>({id:p.id,bounds:{...p.initialBounds}})),refinement:source.refinement||{mode:'existing-aesthetics',references:[]},note:''};}
function migrate(raw){const m=source.layoutMigration;if(!m||raw?.projectId!==source.projectId||raw.mapHash!==m.fromMapHash)return raw;const out=structuredClone(raw),panels=[];for(const p of out.selectedPanels||[]){const children=m.splitPanels[p.id];if(!children){panels.push(p);continue;}if(!p.bounds)throw Error('旧布局坐标缺失');children.forEach((id,i)=>panels.push({id,bounds:{x:p.bounds.x+p.bounds.w*i/children.length,y:p.bounds.y,w:p.bounds.w/children.length,h:p.bounds.h}}));}out.selectedPanels=panels;out.omittedPanelIds=(out.omittedPanelIds||[]).flatMap(id=>m.splitPanels[id]||[id]);out.mapHash=source.mapHash;return out;}
function validate(raw){raw=migrate(raw);if(raw?.schema!=='figure-layout-roundtrip/v1'||raw.projectId!==source.projectId||raw.mapHash!==source.mapHash)throw Error('布局与当前任务不匹配');if(!raw.canvas||raw.canvas.unit!==source.canvas.unit||!['width','height'].every(k=>Number.isFinite(raw.canvas[k])&&raw.canvas[k]===source.canvas[k]))throw Error('画布不匹配，原布局已保留。');const known=new Set(source.panels.map(p=>p.id)),seen=new Set(),p=raw.selectedPanels;if(!Array.isArray(p)||!Array.isArray(raw.omittedPanelIds))throw Error('布局格式无效');const panels=p.map(p=>{if(!known.has(p.id)||seen.has(p.id))throw Error('图片编号重复或不匹配');seen.add(p.id);const b=p.bounds,c=source.canvas;if(!b||!['x','y','w','h'].every(k=>Number.isFinite(b[k]))||b.x<0||b.y<0||b.w<=0||b.h<=0||b.x+b.w>c.width+.01||b.y+b.h>c.height+.01)throw Error('布局坐标无效');return {id:p.id,bounds:{x:b.x,y:b.y,w:b.w,h:b.h}};});for(const id of raw.omittedPanelIds){if(!known.has(id)||seen.has(id))throw Error('图片选择不完整');seen.add(id);}if(seen.size!==known.size)throw Error('图片选择不完整');return {panels,refinement:{mode:raw.refinement?.mode==='user-references'?'user-references':'existing-aesthetics',references:[]},note:typeof raw.note==='string'?raw.note.slice(0,2000):''};}
function output(){return {schema:'figure-layout-roundtrip/v1',projectId:source.projectId,mapHash:source.mapHash,interaction:'browser-layout',canvas:source.canvas,selectedPanels:state.panels.map(p=>({id:p.id,bounds:{...p.bounds}})),omittedPanelIds:source.panels.filter(p=>!state.panels.some(a=>a.id===p.id)).map(p=>p.id),refinement:state.refinement,note:state.note,geometryIsApproximateIntent:true,previewStretchIsNotScientificEdit:true,semanticGuideApprovalRequired:true,userChatApprovalStillRequired:true,scientificSourceEdited:false};}
function localRead(k){try{return JSON.parse(localStorage.getItem(k)||'null');}catch{return null;}}
function localSave(){try{localStorage.setItem(key(),JSON.stringify({layout:output(),baseRevision:revision,dirty:pending,updatedAt:new Date().toISOString()}));}catch{if(pending)$('backup').hidden=false;}}
function current(){return state?.panels.find(p=>p.id===selected);}
function position(box,b){Object.assign(box.style,{left:b.x*PX+'px',top:b.y*PX+'px',width:b.w*PX+'px',height:b.h*PX+'px'});}
function render(){if(!state)return;const canvas=$('canvas');canvas.replaceChildren();canvas.style.width=source.canvas.width*PX+'px';canvas.style.height=source.canvas.height*PX+'px';canvas.style.transform=`scale(${zoom})`;$('sizer').style.width=source.canvas.width*PX*zoom+'px';$('sizer').style.height=source.canvas.height*PX*zoom+'px';for(const p of state.panels){const a=source.panels.find(a=>a.id===p.id),box=element('div','box'+(p.id===selected?' selected':''));box.dataset.id=p.id;box.tabIndex=0;box.setAttribute('role','button');box.setAttribute('aria-label',`${p.id} ${a.name}，可拖动和拉伸`);position(box,p.bounds);if(a.preview){const im=element('img');im.src=a.preview;im.alt=a.name;box.append(im);}box.append(element('span','label',p.id));for(const dir of ['e','s','se','nw','ne','sw']){const h=element('span','handle');h.dataset.dir=dir;box.append(h);}box.addEventListener('pointerdown',e=>startDrag(e,p.id,e.target.dataset.dir));box.addEventListener('focus',()=>{selected=p.id;canvas.querySelectorAll('.box').forEach(b=>b.classList.toggle('selected',b.dataset.id===selected));});canvas.append(box);}}
function fit(){if(!source)return;zoom=clamp(Math.min(($('viewport').clientWidth-40)/(source.canvas.width*PX),($('viewport').clientHeight-40)/(source.canvas.height*PX)),.12,2);render();}
function changed(){pending=true;editVersion++;localSave();status(enabled?'正在同步…':'修改已保存在本机，尚未同步',enabled?'saving':'error');clearTimeout(saveTimer);if(enabled)saveTimer=setTimeout(save,400);else{$('retry').hidden=false;$('backup').hidden=false;}}
function startDrag(e,id,dir){if(e.button!==0||!initialised||$('conflict').open)return;e.preventDefault();selected=id;render();drag={id,dir,x:e.clientX,y:e.clientY,original:{...current().bounds},before:JSON.stringify(state),moved:false};$('canvas').setPointerCapture(e.pointerId);}
$('canvas').addEventListener('pointermove',e=>{if(!drag)return;const dx=(e.clientX-drag.x)/(zoom*PX),dy=(e.clientY-drag.y)/(zoom*PX),b=current().bounds,o=drag.original,c=source.canvas,min=12;if(Math.abs(dx)+Math.abs(dy)<.25&&!drag.moved)return;drag.moved=true;if(!drag.dir){b.x=round(clamp(o.x+dx,0,c.width-o.w));b.y=round(clamp(o.y+dy,0,c.height-o.h));}else{if(drag.dir.includes('e'))b.w=round(clamp(o.w+dx,min,c.width-o.x));if(drag.dir.includes('s'))b.h=round(clamp(o.h+dy,min,c.height-o.y));if(drag.dir.includes('w')){b.x=round(clamp(o.x+dx,0,o.x+o.w-min));b.w=round(o.x+o.w-b.x);}if(drag.dir.includes('n')){b.y=round(clamp(o.y+dy,0,o.y+o.h-min));b.h=round(o.y+o.h-b.y);}}position($('canvas').querySelector(`[data-id="${drag.id}"]`),b);});
function finishDrag(){if(!drag)return;const moved=drag.moved;if(moved){past.push(drag.before);if(past.length>50)past.shift();future=[];}drag=null;render();if(moved)changed();}for(const e of ['pointerup','pointercancel','lostpointercapture'])$('canvas').addEventListener(e,finishDrag);
$('canvas').addEventListener('pointerdown',e=>{if(e.target===$('canvas')){selected=null;render();}});
function undo(redo=false){const from=redo?future:past,to=redo?past:future;if(!from.length)return;to.push(JSON.stringify(state));state=JSON.parse(from.pop());selected=null;render();changed();}
document.addEventListener('keydown',e=>{if($('conflict').open||!initialised)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(!current())return;if(['Delete','Backspace'].includes(e.key)){e.preventDefault();past.push(JSON.stringify(state));future=[];state.panels=state.panels.filter(p=>p.id!==selected);selected=null;render();changed();}if(e.key.startsWith('Arrow')){e.preventDefault();past.push(JSON.stringify(state));future=[];const b=current().bounds,d=e.shiftKey?5:1;if(e.key==='ArrowLeft')b.x-=d;if(e.key==='ArrowRight')b.x+=d;if(e.key==='ArrowUp')b.y-=d;if(e.key==='ArrowDown')b.y+=d;b.x=clamp(b.x,0,source.canvas.width-b.w);b.y=clamp(b.y,0,source.canvas.height-b.h);render();changed();}});
function conflict(env,message){enabled=false;conflictEnvelope=env;status('有另一份布局，等待选择','error');$('conflictMessage').textContent=message;$('conflict').showModal();}
$('conflict').addEventListener('cancel',e=>e.preventDefault());
$('useOnline').onclick=()=>{if(!conflictEnvelope)return;state=conflictEnvelope.layout?validate(conflictEnvelope.layout):initial();revision=conflictEnvelope.revision;pending=false;enabled=true;selected=null;past=[];future=[];localSave();render();$('conflict').close();conflictEnvelope=null;status('已同步');$('retry').hidden=true;$('backup').hidden=true;};
$('keepLocal').onclick=()=>{if(!conflictEnvelope)return;revision=conflictEnvelope.revision;enabled=true;pending=true;$('conflict').close();conflictEnvelope=null;changed();};
async function getRemote(){const r=await fetch('/api/layout',{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error(r.status===401?'请登录后再同步':'暂时无法连接同步服务');const env=await r.json();if(!Number.isInteger(env.revision)||env.revision<0||env.projectId!==source.projectId||env.mapHash!==source.mapHash)throw Error('同步数据不匹配');if(env.layout)validate(env.layout);return env;}
async function save(){if(!enabled||saving||!pending)return;saving=true;const version=editVersion,payload=output(),base=revision;status('正在同步…','saving');try{const r=await fetch('/api/layout',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({expectedRevision:base,layout:payload})});const env=await r.json();if(r.status===409){if(!Number.isInteger(env.revision)||env.projectId!==source.projectId||env.mapHash!==source.mapHash||!env.layout)throw Error('同步冲突，保留本机修改');validate(env.layout);conflict(env,'另一处刚刚保存了不同的布局。两份都已保留，请选择使用哪一份。');return;}if(!r.ok)throw Error(r.status===401?'请登录后再同步':'同步失败，修改已保存在本机');if(env.revision!==base+1||env.projectId!==source.projectId||env.mapHash!==source.mapHash)throw Error('同步确认不完整，修改已保存在本机');revision=env.revision;if(version===editVersion)pending=false;localSave();status(pending?'正在同步…':'已同步',pending?'saving':'');$('retry').hidden=true;$('backup').hidden=true;}catch(e){enabled=false;status(e.message,'error');$('retry').hidden=false;$('backup').hidden=false;localSave();}finally{saving=false;if(enabled&&pending)saveTimer=setTimeout(save,350);}}
$('retry').onclick=async()=>{status('正在重新连接…','saving');try{const env=await getRemote();if(pending&&env.revision!==revision){conflict(env,'在线保存进度发生变化。你的本机修改已保留，请选择要继续的布局。');return;}if(!pending&&env.layout){state=validate(env.layout);revision=env.revision;render();}else revision=env.revision;enabled=true;$('retry').hidden=true;$('backup').hidden=true;if(pending)save();else status('已同步');}catch(e){status(e.message,'error');}};
$('backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(output(),null,2)],{type:'application/json'})),a=element('a');a.href=url;a.download='科研图布局备份.layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
window.addEventListener('resize',fit);window.addEventListener('beforeunload',e=>{if(pending){localSave();e.preventDefault();e.returnValue='';}});window.addEventListener('online',()=>{if(!enabled&&!$('conflict').open)$('retry').click();});
try{const r=await fetch('./project.json',{cache:'no-store'});if(!r.ok)throw Error('无法读取图片布局');source=await r.json();if(source.schema!=='figure-layout-roundtrip/v1'||!Array.isArray(source.panels))throw Error('布局任务格式不支持');state=initial();const backup=localRead(key()),legacy=localRead('figure-layout:'+source.projectId);let local=null;try{if(backup?.layout)local={...backup,dirty:backup.dirty||backup.layout.mapHash!==source.mapHash,state:validate(backup.layout)};else if(legacy)local={layout:legacy,state:validate(legacy),dirty:true,baseRevision:0};}catch{}if(local)state=local.state;initialised=true;render();fit();try{const env=await getRemote();revision=env.revision;if(local?.dirty&&env.layout&&local.baseRevision!==env.revision){pending=true;conflict(env,'此浏览器还有未同步的修改，在线也有另一份布局。请选定继续使用的版本。');}else if(local?.dirty){pending=true;enabled=true;save();}else if(env.layout){state=validate(env.layout);pending=false;enabled=true;localSave();render();status('已同步');}else{enabled=true;pending=true;save();}}catch(e){pending=Boolean(local?.dirty);enabled=false;status(e.message,'error');$('retry').hidden=false;$('backup').hidden=false;}}catch(e){status('加载失败：'+e.message,'error');}
